import {openFeedback} from './feedback.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountNavigation({root,three=false,onAdvanced=()=>{},onStage=()=>{}}){const shell=root.querySelector(three?'.studio3d':'.studio'),abort=new AbortController();let advanced=false,stage='Scene',playing=false;try{advanced=localStorage.getItem('playform.navigation')==='advanced'}catch{}const sidebar=document.createElement('aside');sidebar.className='simple-sidebar';const layout=root.querySelector(three?'.three-layout':'.editor-grid');layout.prepend(sidebar);const nav=document.createElement('div');nav.className='simple-navigation';const groups={Project:[['server-settings','Server & account'],['home','My projects'],['save','Save on this device'],['undo','Undo last change'],['redo','Redo change'],['duplicate','Duplicate selected object'],['delete','Delete selected object'],['import','Open project'],['export','Download project backup'],[three?'windows':'windows-export','Download Windows game']],Game:[[three?'ui':'game-ui','Interface & counters'],[three?'title':'presentation','Title screen (optional)'],[three?'looks':'appearance','Backgrounds & style'],['multiplayer','Play with friends']],Tools:[['sprite','Draw sprites'],['animation','Animate sprites'],['audio','Sounds & effects'],['inputs','Controls'],['camera','Camera'],['physics','Gravity & physics'],['size','Game size'],['debug','Check my game'],['layout','Arrange advanced workspace']]};const source=action=>root.querySelector(`[data-action="${action}"]`);const menu=(name,items)=>`<details class="simple-menu"><summary>${name}</summary><div>${name==='Tools'&&three?'<button data-nav-command="tool:translate">Move objects</button><button data-nav-command="tool:rotate">Rotate objects</button><button data-nav-command="tool:scale">Resize objects</button><button data-nav-command="camera">Camera view</button><button data-nav-command="gravity">Gravity preset</button>':''}${items.filter(([action])=>source(action)).map(([action,label])=>`<button data-nav-action="${action}">${label}</button>`).join('')}</div></details>`;nav.innerHTML=`<div class="simple-top"><button data-nav-action="home" class="simple-home"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18l-6-6 6-6"/></svg> Projects</button><strong>${esc(three?'3D scene':'2D scene')}</strong><span></span>${Object.entries(groups).map(([name,items])=>menu(name,items)).join('')}<button id="navigation-mode" aria-pressed="${advanced}">${advanced?'Simple view':'Advanced view'}</button><button id="navigation-play" class="purple-button">▶ Play</button></div><nav class="simple-stages" aria-label="Editor sections">${[['Scene','Arrange your scene'],['Add','Add characters, objects and scenery'],['Properties','Change the selected object'],['Events','Choose what happens in your game']].map(([name,hint])=>`<button data-stage="${name}" title="${hint}" aria-pressed="${name===stage}">${name}</button>`).join('')}<span class="simple-stage-help"></span></nav>`;shell.prepend(nav);const regions=three?{Scene:[root.querySelector('.three-left')],Add:[root.querySelector('.three-left')],Properties:[root.querySelector('.three-right')],Events:[root.querySelector('.three-events')]}:{Scene:[root.querySelector('[data-dock="explorer"]')],Add:[root.querySelector('[data-dock="library"]'),root.querySelector('[data-dock="assets"]')],Properties:[root.querySelector('[data-dock="inspector"]')],Events:[root.querySelector('[data-dock="workspace"]')]};const originals=new Map([...new Set(Object.values(regions).flat().filter(Boolean))].map(el=>[el,{parent:el.parentElement,next:el.nextSibling}]));if(three){let category='scene';for(const el of root.querySelector('.three-left').children){if(el.tagName==='H3')category=/Scene objects/i.test(el.textContent)?'scene':/World/i.test(el.textContent)?'advanced':'add';el.dataset.simpleCategory=category}}
 function restore(){for(const[el,{parent,next}]of originals)parent.insertBefore(el,next?.parentElement===parent?next:null)}
 const feedbackButton=document.createElement('button');feedbackButton.textContent='Feedback';feedbackButton.onclick=()=>{nav.querySelectorAll('details').forEach(d=>d.open=false);openFeedback()};nav.querySelector('details:last-of-type>div').append(feedbackButton);const modeButton=nav.querySelector('#navigation-mode');function refresh(){if(advanced)nav.querySelector('.simple-top').append(modeButton);else nav.querySelector('details:last-of-type>div').append(modeButton);shell.classList.toggle('simple-editor',!advanced);shell.dataset.stage=stage;shell.dataset.navPlaying=String(playing);nav.querySelector('#navigation-mode').textContent=advanced?'Simple view':'Advanced view';nav.querySelector('#navigation-mode').setAttribute('aria-pressed',advanced);restore();if(!advanced){for(const el of regions[stage]||[])if(el)sidebar.append(el)}nav.querySelectorAll('[data-stage]').forEach(b=>{b.classList.toggle('active',b.dataset.stage===stage);b.setAttribute('aria-pressed',b.dataset.stage===stage);b.disabled=playing});nav.querySelector('.simple-stage-help').textContent=playing?'Your game is running. Stop to keep editing.':({Scene:'Select an object in the scene or list.',Add:'Choose an object, or drag it into the scene.',Properties:'Select an object to change how it looks and moves.',Events:'Choose what starts an event and what happens next.'})[stage];nav.querySelector('#navigation-play').textContent=playing?'■ Stop':'▶ Play';for(const b of nav.querySelectorAll('[data-nav-action]')){const target=source(b.dataset.navAction);b.disabled=!target||target.disabled;b.title=target?.title||b.textContent}onStage(stage,!advanced)}
 function activate(next){if(playing)return;stage=next;refresh()}
 function mode(value){nav.querySelectorAll('details').forEach(d=>d.open=false);advanced=value;restore();try{localStorage.setItem('playform.navigation',advanced?'advanced':'simple')}catch{}onAdvanced(advanced);refresh()}
 nav.querySelectorAll('[data-nav-command]').forEach(b=>b.onclick=()=>{nav.querySelectorAll('details').forEach(d=>d.open=false);const command=b.dataset.navCommand;if(command.startsWith('tool:')){const target=root.querySelector('#three-tool');target.value=command.slice(5);target.dispatchEvent(new Event('change'));return}const target=root.querySelector(command==='camera'?'#three-camera':'#three-gravity'),dialog=document.createElement('dialog');dialog.className='editor-dialog navigation-picker';dialog.innerHTML='<h2>'+(command==='camera'?'Camera view':'Gravity preset')+'</h2><select aria-label="Choose preset">'+target.innerHTML+'</select><footer><button type="button">Cancel</button><button type="button" class="primary">Apply</button></footer>';document.body.append(dialog);dialog.querySelector('select').value=target.value;const buttons=dialog.querySelectorAll('button');buttons[0].onclick=()=>dialog.close();buttons[1].onclick=()=>{target.value=dialog.querySelector('select').value;target.dispatchEvent(new Event('change'));dialog.close()};dialog.onclose=()=>dialog.remove();dialog.showModal()});nav.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>activate(b.dataset.stage));nav.querySelector('#navigation-mode').onclick=()=>mode(!advanced);nav.querySelector('#navigation-play').onclick=()=>{const button=three?source('play'):root.querySelector('#test-game');button?.click();sync()};nav.querySelectorAll('[data-nav-action]').forEach(b=>b.onclick=()=>{nav.querySelectorAll('details').forEach(d=>d.open=false);const action=b.dataset.navAction;if(['layout','inputs','debug'].includes(action)&&!three)mode(true);source(action)?.click();sync()});nav.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){for(const other of nav.querySelectorAll('details'))if(other!==d)other.open=false;for(const b of d.querySelectorAll('[data-nav-action]')){const target=source(b.dataset.navAction);b.disabled=!target||target.disabled;b.title=target?.title||b.textContent}}}));function sync(){nav.querySelectorAll('[data-nav-command]').forEach(b=>b.disabled=playing);const next=three?root.querySelector('#three-play')?.textContent.includes('Stop'):shell.classList.contains('is-playing');if(playing!==next){playing=!!next;refresh()}else for(const b of nav.querySelectorAll('[data-nav-action]')){b.disabled=!!source(b.dataset.navAction)?.disabled}}const timer=setInterval(sync,120);matchMedia('(max-width:700px)').addEventListener('change',()=>refresh(),{signal:abort.signal});document.addEventListener('pointerdown',e=>{if(!nav.contains(e.target))nav.querySelectorAll('details').forEach(d=>d.open=false)},{signal:abort.signal});refresh();return{activate,refresh,sync,isSimple:()=>!advanced,destroy(){clearInterval(timer);abort.abort();restore();nav.remove();sidebar.remove()}}}
